import { getCustomer } from './customers.js';
import { lineTotal, lineDiscount, invoiceTotals, lineVat } from './invoices.js';
import { formatEuros } from './money.js';

/**
 * Render an invoice as plain text.
 * @param {{ number?: string, customerId: string, lines: Array<{ qty: number, name: string, unitPrice: number, discountPercent?: number }>, dueDate?: string, voucher?: { code: string, amount: number }, payments?: Array<{ amount: number }> }} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const customerResult = getCustomer(invoice.customerId);
  const customer = customerResult.value;

  const firstLine = invoice.number ? invoice.number : 'DRAFT';
  const secondLine = customer.name;

  const lineStrings = invoice.lines.map((line) => {
    const total = lineTotal(line);
    let lineStr = `${line.qty}x ${line.name} @ ${formatEuros(line.unitPrice)} = ${formatEuros(total)}`;
    const discount = lineDiscount(line);
    if (discount > 0) {
      lineStr += ` (discount: -${formatEuros(discount)})`;
    }
    return lineStr;
  });

  const totals = invoiceTotals(invoice);
  const subtotalLine = `Subtotal: ${formatEuros(totals.subtotal)}`;
  const discountLine = totals.discount > 0 ? `Discount: -${formatEuros(totals.discount)}` : null;
  const vatLine = totals.vat > 0 ? `VAT: ${formatEuros(totals.vat)}` : null;

  const parts = [firstLine, secondLine, ...lineStrings, subtotalLine];
  if (discountLine) parts.push(discountLine);
  if (vatLine) parts.push(vatLine);

  if (invoice.voucher) {
    parts.push(`Voucher: -${formatEuros(invoice.voucher.amount)}`);
  }

  parts.push(`Total: ${formatEuros(totals.total)}`);

  if (invoice.dueDate) {
    parts.push(`Due: ${invoice.dueDate}`);
  }

  if (invoice.payments && invoice.payments.length > 0) {
    const totalPaid = invoice.payments.reduce((sum, p) => sum + p.amount, 0);
    parts.push(`Paid: ${formatEuros(totalPaid)}`);
  }

  return parts.join('\n');
}

