  });
  const invoice = r.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;
  const r3 = recordPayment(issued, { amount: 2000, date: '2026-10-02' });
  const withPayment = r3.value;

  const text = renderInvoiceText(withPayment);
  assert.match(text, /Paid: €20\.00/);
});

test('renderInvoiceText with full invoice (everything)', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'STICKER', qty: 100 }],
    terms: 'NET14',
  });
  const invoice = r.value;
  const r2 = applyVoucher(invoice, { code: 'SAVE', amount: 500 });
  const withVoucher = r2.value;
  const r3 = issueInvoice(withVoucher, []);
  const issued = r3.value;
  const r4 = recordPayment(issued, { amount: 2000, date: '2026-10-02' });
  const full = r4.value;

  const text = renderInvoiceText(full);
  const lines = text.split('\n');
  assert.match(text, /INV-2026-0001/);
  assert.match(text, /Blue Fern Bakery/);
  assert.match(text, /100x Sticker sheet/);
  assert.match(text, /Voucher: -€5\.00/);
  assert.match(text, /Due: 2026-10-15/);
  assert.match(text, /Paid: €20\.00/);
});

