test('invoiceTotals includes voucher field', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 1000, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.voucher, 0);
});

test('invoiceTotals with voucher reduces total', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 1000, vatRate: 21 }],
    voucher: { code: 'SAVE10', amount: 10000 },
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.voucher, 10000);
  assert.equal(totals.total, 121000 - 10000);
});

test('applyVoucher to a draft invoice', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 100 }],
  });
  const invoice = r.value;

  const r2 = applyVoucher(invoice, { code: 'SAVE50', amount: 5000 });
  assert.equal(r2.ok, true);
  assert.deepEqual(r2.value.voucher, { code: 'SAVE50', amount: 5000 });
});

test('applyVoucher reduces the total', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 100 }],
  });
  const invoice = r.value;

  const totalBefore = invoiceTotals(invoice).total;
  const r2 = applyVoucher(invoice, { code: 'SAVE10', amount: 1000 });
  assert.equal(r2.ok, true);
  const totalAfter = invoiceTotals(r2.value).total;
  assert.equal(totalAfter, totalBefore - 1000);
});

test('applyVoucher rejects non-draft invoices', () => {
