    lines: [{ sku: 'DEV-HOUR', qty: 5, name: 'Development (hour)', unitPrice: 9500, vatRate: 21 }],
  };

  const r = issueInvoice(invoice, []);
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice preserves all invoice data', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2025-01-15',
    lines: [
      { sku: 'COPY-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 2 },
    ],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;

  const r2 = issueInvoice(invoice, ['INV-2025-0005']);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.customerId, 'C-003');
  assert.equal(r2.value.issueDate, '2025-01-15');
  assert.equal(r2.value.lines.length, 2);
  assert.deepEqual(r2.value.lines[0].name, 'Copywriting (hour)');
});

test('issueInvoice does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;
  const originalCopy = JSON.parse(JSON.stringify(invoice));

  issueInvoice(invoice, []);
  assert.deepEqual(invoice, originalCopy);
});
